      "path": "integrations/dsh/runner.mjs",
      "content": "import { spawn } from \"node:child_process\";\nimport { resolveOmaRuntime } from \"./runtime.mjs\";\n\nfunction positiveInteger(value, fallback, label) {\n  const resolved = value ?? fallback;\n  if (!Number.isSafeInteger(resolved) || resolved < 1) {\n    throw new TypeError(`${label} must be a positive integer`);\n  }\n  return resolved;\n}\n\nexport function createHookRunner(config = {}) {\n  const configuredCommand = config.command;\n  const command = configuredCommand ?? process.execPath;\n  const commandArgs = config.commandArgs ?? [];\n  if (typeof command !== \"string\" || !command.trim()) {\n    throw new TypeError(\"command must name an executable\");\n  }\n  if (\n    !Array.isArray(commandArgs) ||\n    commandArgs.some((x) => typeof x !== \"string\")\n  ) {\n    throw new TypeError(\"commandArgs must be an array of strings\");\n  }\n  const timeoutMs = positiveInteger(config.timeoutMs, 10000, \"timeoutMs\");\n  const maxOutputBytes = positiveInteger(\n    config.maxOutputBytes,\n    262144,\n    \"maxOutputBytes\",\n  );\n  const maxInputBytes = positiveInteger(\n    config.maxInputBytes,\n    4194304,\n    \"maxInputBytes\",\n  );\n  const active = new Set();\n  let disposed = false;\n\n  function invocation() {\n    const resolved = resolveOmaRuntime({\n      command: configuredCommand,\n      commandArgs,\n    });\n    return [resolved.command, ...resolved.commandArgs];\n  }\n\n  // `args` replaces the default `hook run` invocation for other OMA commands;\n  // such a command still gets the same isolation, limits and cancellation.\n  function run(event, payload, { signal, owner, args } = {}) {\n    if (disposed || signal?.aborted) {\n      return Promise.reject(new Error(\"OMA hook was cancelled\"));\n    }\n    const stdin = `${JSON.stringify(payload)}\\n`;\n    if (Buffer.byteLength(stdin) > maxInputBytes) {\n      return Promise.reject(new Error(\"OMA hook input exceeds maxInputBytes\"));\n    }\n    const record = { owner, cancel: undefined, done: undefined };\n    record.done = new Promise((resolve, reject) => {\n      let child;\n      let failure;\n      let outputBytes = 0;\n      let stdout = \"\";\n      let stderr = \"\";\n      let terminationTimer;\n      let drainTimer;\n      let finished = false;\n      let closed = false;\n      let escalated = false;\n      const group = process.platform !== \"win32\";\n      function kill(signalName) {\n        if (!child?.pid) return;\n        try {\n          if (group) process.kill(-child.pid, signalName);\n          else child.kill(signalName);\n        } catch (error) {\n          if (error.code !== \"ESRCH\") child.kill(signalName);\n        }\n      }\n      function finish(error) {\n        if (finished) return;\n        finished = true;\n        clearTimeout(timeout);\n        clearTimeout(terminationTimer);\n        clearTimeout(drainTimer);\n        signal?.removeEventListener(\"abort\", abort);\n        active.delete(record);\n        if (error) reject(error);\n        else resolve(stdout);\n      }\n      function terminate(error) {\n        if (failure || finished) return;\n        failure = error;\n        kill(\"SIGTERM\");\n        terminationTimer = setTimeout(() => {\n          kill(\"SIGKILL\");\n          escalated = true;\n          if (closed) finish(failure);\n        }, 250);\n        drainTimer = setTimeout(() => {\n          child?.stdin.destroy();\n          child?.stdout.destroy();\n          child?.stderr.destroy();\n          finish(failure);\n        }, 1000);\n      }\n      const abort = () => terminate(new Error(\"OMA hook was cancelled\"));\n      const timeout = setTimeout(() => {\n        terminate(\n          new Error(`OMA ${event} hook timed out after ${timeoutMs} ms`),\n        );\n      }, timeoutMs);\n      record.cancel = abort;\n      active.add(record);\n      try {\n        const [executable, ...prefixArgs] = invocation();\n        child = spawn(\n          executable,\n          [\n            ...prefixArgs,\n            ...(args ?? [\n              \"hook\",\n              \"run\",\n              \"--vendor\",\n              \"claude\",\n              \"--event\",\n              event,\n            ]),\n          ],\n          {\n            cwd: payload.cwd,\n            shell: false,\n            detached: group,\n            stdio: [\"pipe\", \"pipe\", \"pipe\"],\n            windowsHide: true,\n          },\n        );\n      } catch (error) {\n        finish(error);\n        return;\n      }\n      signal?.addEventListener(\"abort\", abort, { once: true });\n      if (signal?.aborted) abort();\n      child.on(\"error\", (error) => finish(error));\n      child.on(\"close\", (code) => {\n        closed = true;\n        if (failure) {\n          if (escalated) finish(failure);\n          return;\n        }\n        if (code !== 0) {\n          return finish(\n            new Error(`OMA ${event} hook exited ${code}: ${stderr.trim()}`),\n          );\n        }\n        finish();\n      });\n      for (const [stream, channel] of [\n        [child.stdout, \"stdout\"],\n        [child.stderr, \"stderr\"],\n      ]) {\n        stream.setEncoding(\"utf8\");\n        stream.on(\"data\", (chunk) => {\n          outputBytes += Buffer.byteLength(chunk);\n          if (outputBytes > maxOutputBytes) {\n            terminate(new Error(\"OMA hook output exceeds maxOutputBytes\"));\n            return;\n          }\n          if (channel === \"stdout\") stdout += chunk;\n          else stderr += chunk;\n        });\n      }\n      child.stdin.on(\"error\", (error) => {\n        if (error.code !== \"EPIPE\") terminate(error);\n      });\n      child.stdin.end(stdin);\n    });\n    return record.done;\n  }\n\n  async function cancelOwner(owner) {\n    const records = [...active].filter((record) => record.owner === owner);\n    for (const record of records) record.cancel();\n    await Promise.allSettled(records.map((record) => record.done));\n  }\n\n  async function dispose() {\n    disposed = true;\n    const records = [...active];\n    for (const record of records) record.cancel();\n    await Promise.allSettled(records.map((record) => record.done));\n  }\n\n  return { run, invocation, cancelOwner, dispose };\n}\n"
    },
    {
      "path": "integrations/dsh/setup.mjs",
      "content": "import { createHash, randomUUID } from \"node:crypto\";\nimport { constants } from \"node:fs\";\nimport {\n  copyFile,\n  link,\n  lstat,\n  mkdir,\n  mkdtemp,\n  readdir,\n  readFile,\n  realpath,\n  rename,\n  rm,\n  writeFile,\n} from \"node:fs/promises\";\nimport { homedir, tmpdir } from \"node:os\";\nimport { dirname, isAbsolute, join, parse } from \"node:path\";\nimport { setTimeout as delay } from \"node:timers/promises\";\nimport { OMA_VERSION } from \"./runtime.mjs\";\n\nconst MARKERS = [\"oma-config.yaml\", \"oma-config.cue\"];\nconst DIRECTORIES = new Set([\n  \"skills\",\n  \"rules\",\n  \"workflows\",\n  \"agents\",\n  \"config\",\n  \"hooks\",\n]);\nconst MAX_ARCHIVE_BYTES = 64 * 1024 * 1024;\nconst MAX_EXTRACTED_BYTES = 128 * 1024 * 1024;\nconst INITIAL_CONFIG = [\n  \"language: en\",\n  \"model_preset: auto\",\n  \"vendors: []\",\n  \"auto_update_cli: false\",\n  \"providers:\",\n  \"  semantic_memory: none\",\n  \"  code_intelligence_guard: off\",\n  \"\",\n].join(\"\\n\");\n\nasync function info(path) {\n  try {\n    return await lstat(path);\n  } catch (error) {\n    if (error.code === \"ENOENT\" || error.code === \"ENOTDIR\") return undefined;\n    throw error;\n  }\n}\n\nasync function initialized(root) {\n  for (const marker of MARKERS) {\n    // Existing projects can use a symlinked config; resolve it without changing it.\n    try {\n      if ((await lstat(await realpath(join(root, \".agents\", marker)))).isFile())\n        return true;\n    } catch (error) {\n      if (error.code !== \"ENOENT\" && error.code !== \"ENOTDIR\") throw error;\n    }\n  }\n  return false;\n}\n\nexport async function findWorkspace(agent) {\n  const session = agent?.session?.header;\n  const id = agent?.id ?? session?.id;\n  if (\n    typeof session?.cwd !== \"string\" ||\n    !isAbsolute(session.cwd) ||\n    typeof id !== \"string\" ||\n    !id\n  )\n    return undefined;\n  const cwd = await realpath(session.cwd);\n  if (!(await lstat(cwd)).isDirectory())\n    throw new Error(\"OMA workspace must be a directory\");\n  let current = cwd;\n  while (true) {\n    if (await initialized(current)) return { root: current, initialized: true };\n    if (await info(join(current, \".git\")))\n      return { root: current, initialized: false };\n    const parent = dirname(current);\n    if (parent === current) return { root: cwd, initialized: false };\n    current = parent;\n  }\n}\n\n// Release archives contain .agents/ directly. Reject links and unsafe paths\n// before stripping that prefix, and extract only project assets into staging.\nexport function projectArchiveFilter() {\n  let total = 0;\n  return (path, entry) => {\n    const parts = path.replace(/\\/$/, \"\").split(\"/\");\n    if (parts[0] !== \".agents\" || !DIRECTORIES.has(parts[1])) return false;\n    if (\n      parts.some(\n        (part) =>\n          !part ||\n          part === \".\" ||\n          part === \"..\" ||\n          part.includes(\"\\\\\") ||\n          part.includes(\":\"),\n      )\n    )\n      throw new Error(\"Unsafe path in OMA project archive\");\n    if (entry.type !== \"File\" && entry.type !== \"Directory\")\n      throw new Error(\n        \"Links and special files are not allowed in OMA project assets\",\n      );\n    total += entry.size ?? 0;\n    if (total > MAX_EXTRACTED_BYTES || entry.size > 16 * 1024 * 1024)\n      throw new Error(\"OMA project assets exceed the extraction limit\");\n    return true;\n  };\n}\n\nasync function responseBytes(response, limit, signal) {\n  if (!response.ok)\n    throw new Error(\n      `OMA project asset download failed (HTTP ${response.status})`,\n    );\n  if (!response.body)\n    throw new Error(\"OMA project asset download returned an empty body\");\n  const chunks = [];\n  let total = 0;\n  for await (const chunk of response.body) {\n    signal.throwIfAborted();\n    total += chunk.length;\n    if (total > limit)\n      throw new Error(\"OMA project asset download exceeds the size limit\");\n    chunks.push(chunk);\n  }\n  return Buffer.concat(chunks);\n}\n\nexport async function downloadProjectAssets(\n  directory,\n  signal,\n  dependencies = {},\n) {\n  const request = dependencies.fetch ?? globalThis.fetch;\n  const base = `https://github.com/first-fluke/oh-my-agent/releases/download/cli-v${OMA_VERSION}/agent-skills.tar.gz`;\n  const checksum = (\n    await responseBytes(\n      await request(`${base}.sha256`, { signal }),\n      4096,\n      signal,\n    )\n  )\n    .toString(\"utf8\")\n    .trim()\n    .match(/^([a-fA-F0-9]{64})(?:\\s|$)/)?.[1]\n    ?.toLowerCase();\n  if (!checksum)\n    throw new Error(\"OMA project asset checksum is missing or invalid\");\n  const archive = await responseBytes(\n    await request(base, { signal }),\n    MAX_ARCHIVE_BYTES,\n    signal,\n  );\n  if (createHash(\"sha256\").update(archive).digest(\"hex\") !== checksum)\n    throw new Error(\n      \"OMA project asset checksum mismatch; refusing to initialize the project\",\n    );\n  const archivePath = join(dirname(directory), \"agent-skills.tar.gz\");\n  await writeFile(archivePath, archive, { flag: \"wx\" });\n  const extract = dependencies.extract ?? (await import(\"tar\")).x;\n  signal.throwIfAborted();\n  await extract({\n    file: archivePath,\n    cwd: directory,\n    strip: 1,\n    strict: true,\n    preservePaths: false,\n    filter: projectArchiveFilter(),\n    signal,\n  });\n  signal.throwIfAborted();\n  const version = JSON.parse(\n    await readFile(join(directory, \"skills\", \"_version.json\"), \"utf8\"),\n  );\n  if (version.version !== OMA_VERSION)\n    throw new Error(\n      \"OMA project asset version does not match the installed CLI\",\n    );\n  if (!(await info(join(directory, \"skills\", \"oma-qa\", \"SKILL.md\")))?.isFile())\n    throw new Error(\"OMA project assets do not contain the OMA skills\");\n}\n\nasync function mergeMissing(source, destination, signal) {\n  signal.throwIfAborted();\n  const existing = await info(destination